import json,numpy as np
from sklearn.linear_model import Ridge,HuberRegressor
from sklearn.preprocessing import StandardScaler
z=np.load('design.npz');X=z['X'];y=z['y'];gs=z['groups'];keys=list(z['keys']);ug=sorted(set(gs));folds=[(gs!=g,gs==g) for g in ug]
idx=np.array([np.where(gs==g)[0][0] for g in ug]);yi=y[idx];y0=np.array([yi[ug.index(g)] for g in gs]);dy=y-y0
bases={'w':['watts_first'],'wskin':['watts_first','skin_temp_first'],'wage':['watts_first','age'],'wkg':['watts_first','watts_first_kg'],'wsize':['watts_first','mass','height']}
rises={'time':['t','t2'], 'exp':['rise30'], 'work':['t','t2','watts_first_xt'], 'workexp':['rise30','watts_first_xrise'], 'workexp2':['t','t2','watts_first_xrise'], 'workkg':['t','t2','watts_first_xt','watts_first_kg_xt'], 'workkgexp':['t','t2','watts_first_xrise','watts_first_kg_xrise'], 'hr':['t','t2','hr_delta','hr_first_xt','watts_first_xt'], 'heat':['t','t2','watts_mean_kg_xt','hr_mean_xt','skin_temp_mean_xt'], 'heat2':['t','t2','watts_mean_kg_xt','hr_mean_xt','skin_temp_mean_xt','hr_delta','skin_temp_delta'], 'demo':['t','t2','watts_first_xt','age_xt','mass_xt','height_xt'], 'combo':['t','t2','watts_mean_kg_xt','hr_mean_xt','skin_temp_mean_xt','age_xt','hr_delta','skin_temp_delta']}
BP={};RP={};results=[]
for name,ks in bases.items():
 xx=X[:,[keys.index(k) for k in ks]]
 for alpha in [.1,1,10,100]:
  p=np.zeros(len(y))
  for gi,(tr,te) in enumerate(folds):
   ii=idx[gs[idx]!=ug[gi]];s=StandardScaler().fit(xx[ii]);m=Ridge(alpha=alpha).fit(s.transform(xx[ii]),y[ii]);p[te]=m.predict(s.transform(xx[te]))
  BP[(name,alpha)]=p
for name,ks in rises.items():
 xx=X[:,[keys.index(k) for k in ks]]
 for alpha in [1,10,100,1000]:
  p=np.zeros(len(y))
  for tr,te in folds:
   s=StandardScaler(with_mean=False).fit(xx[tr]);m=Ridge(alpha=alpha,fit_intercept=False).fit(s.transform(xx[tr]),dy[tr]);p[te]=m.predict(s.transform(xx[te]))
  RP[(name,alpha)]=p
for bn,bp in BP.items():
 for rn,rp in RP.items():
  pred=bp+rp;mae=np.mean([abs(y[te]-pred[te]).mean() for _,te in folds]);results.append((mae,bn,rn))
print('initial best',sorted([(np.mean(abs(bp[idx]-y[idx])),bn) for bn,bp in BP.items()]))
print('delta best',sorted([(np.mean(abs(rp-dy)),rn) for rn,rp in RP.items()]))
print('BEST',sorted(results)[:40]);json.dump(sorted(results),open('dynamic_results.json','w'));json.dump({'base':bases,'rise':rises},open('dynamic_sets.json','w'))
PY
OPENBLAS_NUM_THREADS=1 python3 cv_dynamic.py"]}

