import numpy as np,json
from sklearn.linear_model import Ridge
from sklearn.preprocessing import StandardScaler
z=np.load('design.npz');X=z['X'];y=z['y'];gs=z['groups'];keys=list(z['keys']);folds=[(gs!=g,gs==g) for g in sorted(set(gs))];sets=json.load(open('feature_sets.json'))
for extra in [['baseline'],['baseline','baseline_xrise'],['hr_mean'],['hr_ema20'],['hr_first_relative'],['hr_ema20','skin_temp_ema20']]:sets['work+'+'+'.join(extra)]=sets['work']+extra
preds={}
for name in ['time','work','work+baseline','work+baseline+baseline_xrise','work+hr_mean','work+hr_ema20','work+hr_first_relative','work+hr_ema20+skin_temp_ema20']:
 xx=X[:,[keys.index(k) for k in sets[name]]]
 for a in [1,10,100,1000]:
  p=np.zeros(len(y))
  for tr,te in folds:
   s=StandardScaler().fit(xx[tr]);m=Ridge(alpha=a).fit(s.transform(xx[tr]),y[tr]);p[te]=m.predict(s.transform(xx[te]))
  preds[name+':'+str(a)]=p
 print(name,[(a,round(np.mean([np.mean(abs(y[te]-preds[name+':'+str(a)][te])) for _,te in folds]),4)) for a in [1,10,100,1000]])
pred=np.load('rf2_predsworkkg.npz')['workkg|absolute_error|4|no'];base=X[:,keys.index('baseline')];print('baseline MAE',np.mean(abs(y-base)))
for b in [0,.2,.4]:
 for a in [0,.1,.2,.3,.5]:
  p=pred*(1-a)+a*(base+b);print('baseline blend',b,a,np.mean(abs(y-p)))
for name in ['time:1','work:10']:
 for a in [0,.1,.2,.3,.5,.75,1]:
  p=(1-a)*pred+a*preds[name];print(name,'blend',a,np.mean(abs(y-p)))
json.dump(sets,open('feature_sets.json','w'));np.savez('blend_preds.npz',**preds)
