{"argv":["bash","-lc","cat > evaluate_ensemble.py <<'PY'
import json,numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge
from sklearn.ensemble import RandomForestRegressor
z=np.load('design.npz');X=z['X'];y=z['y'];gs=z['groups'];keys=list(z['keys']);ug=sorted(set(gs));folds=[(gs!=g,gs==g) for g in ug];sets=json.load(open('feature_sets.json'));ks=sets['workkg'];xx=X[:,[keys.index(k) for k in ks]]
ps={name:np.zeros(len(y)) for name in ['forest_sq','forest_abs','work','time']}
for tr,te in folds:
 for name,crit,dep in [('forest_sq','squared_error',3),('forest_abs','absolute_error',4)]:
  m=RandomForestRegressor(n_estimators=200,max_depth=dep,min_samples_leaf=10,max_features=.8,criterion=crit,random_state=42,n_jobs=1).fit(xx[tr],y[tr]);ps[name][te]=m.predict(xx[te])
 for name,a in [('work',10),('time',1)]:
  bx=X[:,[keys.index(k) for k in sets[name]]];s=StandardScaler().fit(bx[tr]);m=Ridge(alpha=a).fit(s.transform(bx[tr]),y[tr]);ps[name][te]=m.predict(s.transform(bx[te]))
ps['baseline']=X[:,keys.index('baseline')]+.4
rows=[]
for sq in [0,.25,.5,.75,1]:
 for work in [0,.1,.2,.3,.5]:
  for base in [0,.1,.2]:
   if work+base>1:continue
   p=(1-work-base)*((1-sq)*ps['forest_abs']+sq*ps['forest_sq'])+work*ps['work']+base*ps['baseline']
   shift=float(np.median(y-p));pred=p+shift
   err=np.mean([abs(pred[te]-y[te]).mean() for _,te in folds]);rows.append((err,sq,work,base,shift))
print('models',[(k,np.mean([abs(v[te]-y[te]).mean() for _,te in folds])) for k,v in ps.items()]);print('top',sorted(rows)[:30]);np.savez('ensemble_oof.npz',**ps);json.dump(sorted(rows),open('ensemble_results.json','w'))
PY
